SELECT "On_Time_On_Time_Performance_2016_1"."Div1TotalGTime", "On_Time_On_Time_Performance_2016_1"."Div1Airport", "L_MONTHS"."Code", "L_UNIQUE_CARRIERS"."Description"
FROM "L_MONTHS" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_MONTHS"."Code" = "On_Time_On_Time_Performance_2016_1"."Month" LEFT JOIN "L_UNIQUE_CARRIERS" ON "On_Time_On_Time_Performance_2016_1"."UniqueCarrier" = "L_UNIQUE_CARRIERS"."Code" LIMIT 65;

SELECT "L_STATE_FIPS"."Description", "L_STATE_FIPS"."Code"
FROM "L_STATE_FIPS" WHERE "L_STATE_FIPS"."Description" = 'Oregon' AND "L_STATE_FIPS"."Description" != 'Johnston Atoll' AND "L_STATE_FIPS"."Code" != 97 LIMIT 44;

SELECT "On_Time_On_Time_Performance_2016_1"."FirstDepTime", "L_QUARTERS"."Description", "On_Time_On_Time_Performance_2016_1"."Div2WheelsOn"
FROM "L_QUARTERS" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_QUARTERS"."Code" = "On_Time_On_Time_Performance_2016_1"."Quarter" WHERE "On_Time_On_Time_Performance_2016_1"."DestState" = 'CA' AND "L_QUARTERS"."Code" <= 3 AND "L_QUARTERS"."Description" = 'Quarter3:July 1-September 30' LIMIT 14;

SELECT "L_ONTIME_DELAY_GROUPS"."Code", "L_ONTIME_DELAY_GROUPS"."Description", "L_ONTIME_DELAY_GROUPS"."Description", "On_Time_On_Time_Performance_2016_1"."CarrierDelay"
FROM "L_ONTIME_DELAY_GROUPS" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_ONTIME_DELAY_GROUPS"."Code" = "On_Time_On_Time_Performance_2016_1"."ArrivalDelayGroups" WHERE "On_Time_On_Time_Performance_2016_1"."Distance" >= 2395.598772332449 LIMIT 4;

SELECT "On_Time_On_Time_Performance_2016_1"."OriginCityName", "L_CITY_MARKET_ID"."Description", "L_CITY_MARKET_ID"."Code", "L_QUARTERS"."Code", "L_QUARTERS"."Code"
FROM "L_CITY_MARKET_ID" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_CITY_MARKET_ID"."Code" = "On_Time_On_Time_Performance_2016_1"."OriginCityMarketID" LEFT JOIN "L_QUARTERS" ON "On_Time_On_Time_Performance_2016_1"."Quarter" = "L_QUARTERS"."Code" WHERE "L_CITY_MARKET_ID"."Code" = 31291 AND "L_QUARTERS"."Description" != 'Quarter4:October 1-December 31' LIMIT 75;

SELECT "L_YESNO_RESP"."Code", "On_Time_On_Time_Performance_2016_1"."Div2LongestGTime", "On_Time_On_Time_Performance_2016_1"."DivReachedDest", "L_YESNO_RESP"."Code"
FROM "L_AIRPORT_SEQ_ID" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_AIRPORT_SEQ_ID"."Code" = "On_Time_On_Time_Performance_2016_1"."DestAirportSeqID" LEFT JOIN "L_YESNO_RESP" ON "On_Time_On_Time_Performance_2016_1"."Cancelled" = "L_YESNO_RESP"."Code" WHERE "L_YESNO_RESP"."Description" != 'Yes' AND "L_AIRPORT_SEQ_ID"."Code" <= 1066263 AND "L_YESNO_RESP"."Description" != 'No' LIMIT 48;

SELECT "L_STATE_ABR_AVIATION"."Code", "On_Time_On_Time_Performance_2016_1"."TaxiIn", "L_AIRPORT_SEQ_ID"."Code", "On_Time_On_Time_Performance_2016_1"."WeatherDelay"
FROM "L_AIRPORT_SEQ_ID" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_AIRPORT_SEQ_ID"."Code" = "On_Time_On_Time_Performance_2016_1"."OriginAirportSeqID" JOIN "L_STATE_ABR_AVIATION" ON "On_Time_On_Time_Performance_2016_1"."OriginState" = "L_STATE_ABR_AVIATION"."Code" WHERE "On_Time_On_Time_Performance_2016_1"."Div1LongestGTime" IS NOT NULL AND "L_STATE_ABR_AVIATION"."Description" = 'Saskatchewan, Canada' LIMIT 2;

SELECT "L_YESNO_RESP"."Description", "L_AIRPORT_ID"."Description"
FROM "L_YESNO_RESP" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_YESNO_RESP"."Code" = "On_Time_On_Time_Performance_2016_1"."ArrDel15" LEFT JOIN "L_AIRPORT_ID" ON "On_Time_On_Time_Performance_2016_1"."DestAirportID" = "L_AIRPORT_ID"."Code" WHERE "L_AIRPORT_ID"."Code" = 29130 LIMIT 84;

SELECT "L_AIRPORT"."Description", "L_AIRPORT"."Code", "On_Time_On_Time_Performance_2016_1"."DestState"
FROM "L_AIRPORT" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_AIRPORT"."Code" = "On_Time_On_Time_Performance_2016_1"."Dest" JOIN "L_AIRPORT_SEQ_ID" ON "On_Time_On_Time_Performance_2016_1"."Div1AirportSeqID" = "L_AIRPORT_SEQ_ID"."Code" WHERE "L_AIRPORT_SEQ_ID"."Description" != 'San Diego, CA: Miramar MCAS' LIMIT 42;

SELECT "On_Time_On_Time_Performance_2016_1"."DepTimeBlk", "L_AIRPORT_SEQ_ID"."Code"
FROM "L_CANCELLATION" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_CANCELLATION"."Code" = "On_Time_On_Time_Performance_2016_1"."CancellationCode" JOIN "L_AIRPORT_SEQ_ID" ON "On_Time_On_Time_Performance_2016_1"."Div2AirportSeqID" = "L_AIRPORT_SEQ_ID"."Code" WHERE "L_CANCELLATION"."Description" != 'National Air System' LIMIT 72;

SELECT "L_QUARTERS"."Code", "L_QUARTERS"."Description", "On_Time_On_Time_Performance_2016_1"."Div2Airport"
FROM "L_QUARTERS" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_QUARTERS"."Code" = "On_Time_On_Time_Performance_2016_1"."Quarter" WHERE "On_Time_On_Time_Performance_2016_1"."DepTimeBlk" = '0700-0759' AND "L_QUARTERS"."Code" != 2 LIMIT 32;

SELECT "L_DEPARRBLK"."Description", "On_Time_On_Time_Performance_2016_1"."Div2LongestGTime", "On_Time_On_Time_Performance_2016_1"."Origin"
FROM "L_UNIQUE_CARRIERS" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_UNIQUE_CARRIERS"."Code" = "On_Time_On_Time_Performance_2016_1"."UniqueCarrier" JOIN "L_DEPARRBLK" ON "On_Time_On_Time_Performance_2016_1"."DepTimeBlk" = "L_DEPARRBLK"."Code" WHERE "L_DEPARRBLK"."Code" = '1500-1559' AND "L_UNIQUE_CARRIERS"."Code" != 'AND' AND "On_Time_On_Time_Performance_2016_1"."DivReachedDest" >= 1.0901533800470191 LIMIT 66;

SELECT "L_STATE_FIPS"."Description", "L_STATE_FIPS"."Code"
FROM "L_STATE_FIPS" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_STATE_FIPS"."Code" = "On_Time_On_Time_Performance_2016_1"."DestStateFips" WHERE "L_STATE_FIPS"."Description" = 'Not Applicable' LIMIT 5;

SELECT "On_Time_On_Time_Performance_2016_1"."Div2TotalGTime", "L_AIRLINE_ID"."Code", "On_Time_On_Time_Performance_2016_1"."LongestAddGTime"
FROM "L_AIRLINE_ID" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_AIRLINE_ID"."Code" = "On_Time_On_Time_Performance_2016_1"."AirlineID" WHERE "On_Time_On_Time_Performance_2016_1"."DepDel15" != -2 LIMIT 80;

SELECT "On_Time_On_Time_Performance_2016_1"."DivAirportLandings", "L_DIVERSIONS"."Code"
FROM "L_DEPARRBLK" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_DEPARRBLK"."Code" = "On_Time_On_Time_Performance_2016_1"."DepTimeBlk" LEFT JOIN "L_DIVERSIONS" ON "On_Time_On_Time_Performance_2016_1"."DivAirportLandings" = "L_DIVERSIONS"."Code" WHERE "L_DIVERSIONS"."Code" = 8 LIMIT 48;

SELECT "L_YESNO_RESP"."Code", "L_DIVERSIONS"."Code", "On_Time_On_Time_Performance_2016_1"."ArrTime"
FROM "L_DIVERSIONS" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_DIVERSIONS"."Code" = "On_Time_On_Time_Performance_2016_1"."DivAirportLandings" JOIN "L_YESNO_RESP" ON "On_Time_On_Time_Performance_2016_1"."Diverted" = "L_YESNO_RESP"."Code" WHERE "L_DIVERSIONS"."Code" = 4 LIMIT 43;

SELECT "L_ONTIME_DELAY_GROUPS"."Description", "L_ONTIME_DELAY_GROUPS"."Code", "L_STATE_FIPS"."Code", "On_Time_On_Time_Performance_2016_1"."OriginStateName"
FROM "L_STATE_FIPS" LEFT JOIN "On_Time_On_Time_Performance_2016_1" ON "L_STATE_FIPS"."Code" = "On_Time_On_Time_Performance_2016_1"."OriginStateFips" LEFT JOIN "L_ONTIME_DELAY_GROUPS" ON "On_Time_On_Time_Performance_2016_1"."DepartureDelayGroups" = "L_ONTIME_DELAY_GROUPS"."Code" WHERE "L_STATE_FIPS"."Description" = 'South Dakota' AND "L_ONTIME_DELAY_GROUPS"."Description" != 'Delay between 0 and 14 minutes' AND "L_ONTIME_DELAY_GROUPS"."Description" != 'Delay between 165 to 179 minutes' LIMIT 48;

SELECT "L_WORLD_AREA_CODES"."Code", "L_WORLD_AREA_CODES"."Description", "On_Time_On_Time_Performance_2016_1"."CancellationCode", "On_Time_On_Time_Performance_2016_1"."DestState"
FROM "On_Time_On_Time_Performance_2016_1" JOIN "L_WORLD_AREA_CODES" ON "On_Time_On_Time_Performance_2016_1"."OriginWac" = "L_WORLD_AREA_CODES"."Code" JOIN "L_YESNO_RESP" ON "On_Time_On_Time_Performance_2016_1"."DepDel15" = "L_YESNO_RESP"."Code" WHERE "L_YESNO_RESP"."Description" = 'No' AND "L_YESNO_RESP"."Code" <= 0 LIMIT 69;

SELECT "L_AIRPORT_SEQ_ID"."Code", "L_AIRPORT_SEQ_ID"."Code", "On_Time_On_Time_Performance_2016_1"."DestState", "L_STATE_ABR_AVIATION"."Description", "L_STATE_ABR_AVIATION"."Description"
FROM "L_STATE_ABR_AVIATION" JOIN "On_Time_On_Time_Performance_2016_1" ON "L_STATE_ABR_AVIATION"."Code" = "On_Time_On_Time_Performance_2016_1"."DestState" JOIN "L_AIRPORT_SEQ_ID" ON "On_Time_On_Time_Performance_2016_1"."OriginAirportSeqID" = "L_AIRPORT_SEQ_ID"."Code" LIMIT 28;

